begin
  perform net.http_post(
    url := 'https://zqgzcspeqllrihfwmayn.supabase.co/functions/v1/hydrate-ticket-urls',
    body := '{"limit": 60}'::jsonb,
    headers := jsonb_build_object('Content-Type', 'application/json',
